/** Builds content/packs/index.generated.ts: Metro cannot glob, so packs are listed explicitly. */

const HEADER =
  '// Generated by `pnpm content:index` from content/packs/*.json. Do not edit by hand.';

/** "fullstack-backend-node.json" → "fullstackBackendNode". */
export function toIdentifier(fileName: string): string {
  const base = fileName.replace(/\.json$/, '');
  const camel = base.replace(/[-_.]+([a-z0-9])/gi, (_, char: string) => char.toUpperCase());
  return /^[0-9]/.test(camel) ? `pack${camel}` : camel;
}

export function renderManifest(packFileNames: readonly string[]): string {
  const files = [...packFileNames].sort();
  if (files.length === 0) {
    return `${HEADER}\n\nexport const bundledPacks: readonly unknown[] = [];\n`;
  }
  const imports = files.map(file => `import ${toIdentifier(file)} from './${file}';`);
  const list = files.map(file => `  ${toIdentifier(file)},`);
  return [
    HEADER,
    '',
    ...imports,
    '',
    'export const bundledPacks: readonly unknown[] = [',
    ...list,
    '];',
    '',
  ].join('\n');
}
